/**
 * 本地聊天的开关由插件提供（capability: console.chat.meta）。
 * 没装插件 / 插件被关掉 → 返回 null，相关接口一律 404，界面上的页签也不会出现。
 */
function localChatMeta() {
  try {
    const providers = skillManager.getCapabilityProviders('console.chat.meta', {});
    for (const p of providers || []) {
      try {
        const meta = typeof p?.fn === 'function' ? p.fn({}) : null;
        if (meta && meta.enabled !== false) return { title: String(meta.title || '聊天') };
      } catch { /* 提供者抛错 = 当作没这个能力 */ }
    }
  } catch { /* skillManager 还没就绪 */ }
  return null;
}

// ── 多会话（聊天页可新建/切换对话）────────────────────────────────
// 会话 key 一律 local:<slug>；标题存 data/local-chat-sessions.json（消息本体仍在 data/messages）
const LOCAL_SESSIONS_FILE = path.join(DATA_DIR, 'local-chat-sessions.json');
const LOCAL_KEY_RE = /^local:[a-z0-9_-]{1,32}$/i;

function readSessionTitles() {
  try {
    const j = JSON.parse(fs.readFileSync(LOCAL_SESSIONS_FILE, 'utf8'));
    return (j && typeof j.titles === 'object' && j.titles) || {};
  } catch { return {}; }
}

function setLocalTitle(key, title) {
  const all = readSessionTitles();
  all[String(key)] = String(title || '').slice(0, 40);
  try {
    fs.mkdirSync(path.dirname(LOCAL_SESSIONS_FILE), { recursive: true });
    fs.writeFileSync(LOCAL_SESSIONS_FILE, JSON.stringify({ titles: all }, null, 1), 'utf8');
  } catch (e) { log('[local-chat] 保存会话标题失败：' + (e?.message ?? e)); }
}

/** 把请求里的 session 参数规范化：只认 local:*，认不出就回默认会话。 */
function localKeyOf(v) {
  const k = String(v ?? '').trim();
  return LOCAL_KEY_RE.test(k) ? k : LOCAL_CHAT_KEY;
}

/** 会话序号：local:console 算 1，local:s12 算 12（用于默认标题）。 */
function localSessionNo(key) {
  const m = /^local:s(\d+)$/i.exec(String(key));
  if (m) return Number(m[1]);
  return 1;
}

/** 新建一个会话 key（序号递增，跳过已存在的）。 */
function newLocalKey() {
  const used = new Set(store.listChats().filter((k) => String(k).startsWith('local:')));
  let n = 1;
  while (used.has('local:s' + n)) n += 1;
  return 'local:s' + n;
}

/** 会话列表：以"有消息文件的 local:*"为准，标题读 meta，按最近活动排序。 */
function listLocalSessions() {
  const titles = readSessionTitles();
  const keys = store.listChats().filter((k) => String(k).startsWith('local:'));
  if (!keys.includes(LOCAL_CHAT_KEY)) keys.push(LOCAL_CHAT_KEY);
  return keys.map((k) => {
    const meta = store.getChatMeta(k) || {};
    return {
      key: k,
      title: titles[k] || (k === LOCAL_CHAT_KEY ? '主对话' : ('对话 ' + localSessionNo(k))),
      count: meta.total || 0,
      lastTs: meta.lastTs || 0,
      lastText: meta.lastText || ''
    };
  }).sort((a, b) => (b.lastTs || 0) - (a.lastTs || 0));
}

/** 记忆成员映射（前端直接用）。 */
function mapMemoryMembers(chatKey) {
  return (memory.members(chatKey) || []).map((m) => ({
    userId: m.userId,
    name: m.name || '',
    impressions: (m.impressions || []).map((e, i) => ({ index: i, content: e.content, createdAt: e.createdAt || 0 }))
  }));
}

