// ── 会话记忆：直接读写 data/memory 下这个会话的记忆文件 ──
{
  method: 'GET', pattern: '/api/local-chat/memory',
  handler: async ({ res, json, url }) => {
    if (!localChatMeta()) return json(res, 404, { error: '本地聊天未启用' });
    const key = localKeyOf(url.searchParams.get('session'));
