{
  method: 'POST', pattern: '/api/local-chat/memory/delete',
  handler: async ({ req, res, json }) => {
    if (!localChatMeta()) return json(res, 404, { error: '本地聊天未启用' });
    const body = await bodyOf(req);
    const key = localKeyOf(body.session);
    const userId = String(body.userId ?? '').trim();
    const indexes = (Array.isArray(body.indexes) ? body.indexes : [body.index]).map((n) => Number(n)).filter((n) => Number.isInteger(n) && n >= 0);
    if (!userId) return json(res, 400, { error: '缺少 userId' });
    if (!indexes.length) return json(res, 400, { error: '缺少要删的条目序号' });
    const member = (memory.members(key) || []).find((m) => String(m.userId) === userId);
    if (!member) return json(res, 404, { error: '没有这个成员的记忆' });
    const keep = (member.impressions || []).filter((_, i) => !indexes.includes(i));
    const removed = (member.impressions || []).length - keep.length;
    memory.editMemberImpression(key, {
      userId: member.userId,
      name: member.name || '',
      impressions: keep.map((x) => ({ content: x.content, createdAt: x.createdAt }))
    });
    log('[local-chat] ' + key + ' 删掉 ' + removed + ' 条记忆');
    return json(res, 200, { ok: true, removed, left: keep.length, members: mapMemoryMembers(key) });
  }
},
{
  method: 'POST', pattern: '/api/local-chat/memory/clear',
  handler: async ({ req, res, json }) => {
    if (!localChatMeta()) return json(res, 404, { error: '本地聊天未启用' });
    const body = await bodyOf(req);
    const key = localKeyOf(body.session);
    const userId = String(body.userId ?? '').trim();
    if (userId) {
      // 只清某个成员：整段成员文件删掉
      const ok = memory.removeMember(key, userId);
      log('[local-chat] ' + key + ' 清空成员记忆 ' + userId + '（' + (ok ? '已删' : '没找到') + '）');
      return json(res, 200, { ok: true, scope: 'member', members: mapMemoryMembers(key) });
    }
    memory.removeChat(key);
    log('[local-chat] ' + key + ' 清空整个会话记忆');
    return json(res, 200, { ok: true, scope: 'session', members: [] });
  }
},

