// 本地聊天页：在软件界面里直接和 Agent 对话，不经过 QQ。
//
// 链路与 QQ 完全一致 —— 只是会话 key 换成 local:*：
//   POST /api/local-chat/send → store 入库 → orchestrator 判定 → 模型
//   → send_message 工具 → sender 看到 local: 前缀就写回库，不发往 QQ。
// 所以人设、记忆、插件、工具全都沿用，不需要第二套逻辑。
//
// 多会话（2026-10-22）：每个 local:<slug> 是一段独立对话，消息与记忆各存一份。
// 记忆面板直接读写 data/memory 下这个会话的记忆文件 —— 删了就是真删。
(function () {
  const DEFAULT_KEY = 'local:console';
  let session = localStorage.getItem('lc.session') || DEFAULT_KEY;
  let messages = [];
  let pending = false;
  let loadTimer = null;
  let sse = null;

  const $id = (id) => document.getElementById(id);
  const qs = (s) => `${s}${s.includes('?') ? '&' : '?'}session=${encodeURIComponent(session)}`;

  let pendingTimer = null;
  // 统一入口：开/关"正在输入"并带看门狗。她决定不说话时，指示器不会永远转下去。
  function setPending(on) {
    pending = Boolean(on);
    if (pendingTimer) { clearTimeout(pendingTimer); pendingTimer = null; }
    if (pending) {
      pendingTimer = setTimeout(() => { pending = false; pendingTimer = null; render(); }, 90000);
    }
    render();
  }

  function nearBottom(el) {
    return el.scrollHeight - el.scrollTop - el.clientHeight < 80;
  }

  function bubbleHtml(m) {
    const who = m.self ? '我' : (m.senderName || '我');
    const cls = m.self ? 'lc-row lc-self' : 'lc-row lc-them';
    const body = esc(String(m.text || '')).replace(/\n/g, '<br>');
    const time = fmtClock(m.ts || Date.now());
    const editable = Number.isFinite(Number(m.id));
    const tools = editable
      ? `<span class="lc-tools"><button class="lc-tool" data-act="edit" title="修改这条">✏️</button><button class="lc-tool" data-act="del" title="删除这条">🗑</button></span>`
      : '';
    return `<div class="${cls}" data-id="${m.id}">
      <div class="lc-meta"><span class="lc-meta-text">${esc(who)} · ${time}</span>${tools}</div>
      <div class="lc-bubble">${body || '<span class="muted">（空消息）</span>'}</div>
    </div>`;
  }

  // ── 单条消息的修改 / 删除 ────────────────────────────────────
  function startEdit(row) {
    if (!row || row.querySelector('.lc-editbox')) return;
    const id = Number(row.dataset.id);
    const msg = messages.find((m) => Number(m.id) === id);
    if (!msg) return;
    const bubble = row.querySelector('.lc-bubble');
    if (!bubble) return;
    bubble.innerHTML = `<textarea class="lc-editbox" rows="2">${esc(String(msg.text || ''))}</textarea>
      <div class="lc-editbar"><button class="btn btn-small btn-primary" data-act="save">保存</button><button class="btn btn-small" data-act="cancel">取消</button></div>`;
    const box = bubble.querySelector('.lc-editbox');
    box.focus();
    box.setSelectionRange(box.value.length, box.value.length);
    box.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') { e.preventDefault(); render(); }
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); saveEdit(row, id, box.value); }
    });
    bubble.querySelector('[data-act="save"]').addEventListener('click', () => saveEdit(row, id, box.value));
    bubble.querySelector('[data-act="cancel"]').addEventListener('click', () => render());
  }

  async function saveEdit(row, id, text) {
    const v = String(text || '').trim();
    if (!v) { if (typeof toast === 'function') toast('内容不能为空，要删就用删除', 'error'); return; }
    try {
      await api('/api/local-chat/message/update', { method: 'POST', body: JSON.stringify({ session, id, text: v }) });
      const msg = messages.find((m) => Number(m.id) === id);
      if (msg) msg.text = v;
      render();
      if (typeof toast === 'function') toast('已修改', 'ok');
    } catch (e) {
      if (typeof toast === 'function') toast(`修改失败：${e.message}`, 'error');
    }
  }

  async function deleteOne(row, id) {
    const msg = messages.find((m) => Number(m.id) === id);
    const preview = String(msg?.text || '').slice(0, 30);
    const ask = typeof uiConfirm === 'function'
      ? await uiConfirm(`删掉这条消息？

${preview}${preview.length >= 30 ? '…' : ''}

（只删消息，不影响记忆）`)
      : window.confirm('删掉这条消息？');
    if (!ask) return;
    try {
      await api('/api/local-chat/message/delete', { method: 'POST', body: JSON.stringify({ session, id }) });
      messages = messages.filter((m) => Number(m.id) !== id);
      render();
    } catch (e) {
      if (typeof toast === 'function') toast(`删除失败：${e.message}`, 'error');
    }
  }

  function render() {
    const host = $id('livechat-messages');
    if (!host) return;
    const stick = nearBottom(host);
    if (!messages.length) {
      host.innerHTML = '<div class="livechat-empty muted">说点什么吧～这里的对话和人设都跟 QQ 里一致</div>';
      return;
    }
    host.innerHTML = messages.map(bubbleHtml).join('')
      + (pending ? '<div class="lc-row lc-them lc-pending"><div class="lc-meta">对方</div><div class="lc-bubble"><span class="lc-dots"><i></i><i></i><i></i></span></div></div>' : '');
    if (stick) host.scrollTop = host.scrollHeight;
  }

  async function load() {
    try {
      const data = await api(qs('/api/local-chat/messages?limit=200'));
      // 切会话时可能有旧请求回流：只认当前会话
      if (data.chatKey && data.chatKey !== session) return;
      const list = Array.isArray(data.messages) ? data.messages : [];
      const changed = list.length !== messages.length ||
        (list.length && messages.length && list[list.length - 1].id !== messages[messages.length - 1].id);
      messages = list;
      const last = messages[messages.length - 1];
      if (last && last.self && pending) setPending(false);
      if (changed) render();
    } catch (e) {
      /* 后端没起来时静默，下次轮询再试 */
    }
  }

  async function send() {
    const input = $id('livechat-input');
    if (!input) return;
    const text = String(input.value || '').trim();
    if (!text) return;
    input.value = '';
    autoGrow(input);
    setPending(true);
    messages = messages.concat([{
      id: `temp-${Date.now()}`, ts: Date.now(), text, self: false, senderName: '主人'
    }]);
    render();
    try {
      await api('/api/local-chat/send', { method: 'POST', body: JSON.stringify({ session, text }) });
      const host = $id('livechat-messages');
      if (host) host.scrollTop = host.scrollHeight;
      load();
    } catch (e) {
      setPending(false);
      messages = messages.filter((m) => !String(m.id).startsWith('temp-'));
      render();
      if (typeof toast === 'function') toast(`发送失败：${e.message}`, 'error');
      else console.error('发送失败:', e);
    }
  }

  function autoGrow(el) {
    el.style.height = 'auto';
    el.style.height = `${Math.min(180, el.scrollHeight)}px`;
  }

  function startPolling() {
    stopPolling();
    loadTimer = setInterval(() => {
      const view = $id('view-livechat');
      if (view && !view.classList.contains('active')) return;
      load();
    }, 1200);
  }

  function stopPolling() {
    if (loadTimer) { clearInterval(loadTimer); loadTimer = null; }
  }

  function bindSse() {
    try {
      sse = new EventSource('/api/events');
      sse.addEventListener('chat-update', (ev) => {
        let key = '';
        try { key = String(JSON.parse(ev.data || '{}').chatKey || ev.data || ''); } catch { key = String(ev.data || ''); }
        if (key && key !== session) return;
        const view = $id('view-livechat');
        if (view && !view.classList.contains('active')) return;
        load();
      });
    } catch { /* SSE 不可用时退回纯轮询 */ }
  }

  function onShow() {
    load();
    loadSessions();
    startPolling();
    setTimeout(() => {
      const input = $id('livechat-input');
      if (input) input.focus();
      const host = $id('livechat-messages');
      if (host) host.scrollTop = host.scrollHeight;
    }, 30);
  }

  // ── 会话：切换 / 新建 / 改名 ─────────────────────────────────
  function fillSessionSelect(sessions) {
    const sel = $id('livechat-session');
    if (!sel) return;
    if (!sessions || !sessions.length) return;
    if (!sessions.some((s) => s.key === session)) session = sessions[0].key;
    sel.innerHTML = sessions.map((s) => {
      const tag = s.count ? `（${s.count}）` : '';
      return `<option value="${esc(s.key)}"${s.key === session ? ' selected' : ''}>${esc(s.title + tag)}</option>`;
    }).join('');
  }

  async function loadSessions() {
    try {
      const data = await api('/api/local-chat/sessions');
      fillSessionSelect(data.sessions);
    } catch { /* 老后端没有这个接口：只用一个默认会话 */ }
  }

  function switchSession(key) {
    const next = String(key || '');
    if (!next || next === session) return;
    session = next;
    try { localStorage.setItem('lc.session', session); } catch { /* ignore */ }
    messages = [];
    setPending(false);
    render();
    load();
  }

  async function createSession() {
    try {
      const data = await api('/api/local-chat/sessions', { method: 'POST', body: JSON.stringify({}) });
      await loadSessions();
      if (data.key) switchSession(data.key);
      if (typeof toast === 'function') toast('新对话已建好，记忆是独立的', 'ok');
      const input = $id('livechat-input');
      if (input) input.focus();
    } catch (e) {
      if (typeof toast === 'function') toast(`新建失败：${e.message}`, 'error');
    }
  }

  async function deleteSession() {
    const sel = $id('livechat-session');
    const label = sel && sel.selectedIndex >= 0 ? sel.options[sel.selectedIndex].textContent : session;
    const ask = typeof uiConfirm === 'function'
      ? await uiConfirm('删除对话「' + label + '」？\n\n消息和这段对话的记忆都会一起删掉，删了找不回来。')
      : window.confirm('删除这个对话？消息和记忆都会删掉');
    if (!ask) return;
    try {
      const data = await api('/api/local-chat/sessions/delete', { method: 'POST', body: JSON.stringify({ session }) });
      const next = data.next || DEFAULT_KEY;
      messages = [];
      session = next;
      try { localStorage.setItem('lc.session', session); } catch { /* ignore */ }
      await loadSessions();
      render();
      load();
      if (typeof toast === 'function') toast('对话已删除', 'ok');
    } catch (e) {
      if (typeof toast === 'function') toast('删除失败：' + e.message, 'error');
    }
  }

  // ── 会话记忆：列出 + 单条删 + 整个清 ─────────────────────────
  async function openMemory() {
    const panel = $id('livechat-mem-panel');
    const body = $id('livechat-mem-body');
    if (!panel || !body) return;
    panel.classList.remove('hidden');
    body.innerHTML = '<div class="muted" style="padding:12px">正在读取…</div>';
    try {
      const data = await api(qs('/api/local-chat/memory'));
      const members = Array.isArray(data.members) ? data.members : [];
      const rows = [];
      let total = 0;
      for (const m of members) {
        const list = Array.isArray(m.impressions) ? m.impressions : [];
        if (!list.length) continue;
        total += list.length;
        rows.push(`<div class="lc-mem-who">${esc(m.name || m.userId)}
          <button class="lc-mem-clear" data-user="${esc(m.userId)}" title="清空这个人的全部记忆">清空</button></div>`);
        for (const it of list) {
          rows.push(`<div class="lc-mem-row" data-u="${esc(m.userId)}" data-i="${it.index}">
            <span class="lc-mem-text">${esc(it.content)}</span>
            <button class="lc-mem-del" title="删掉这一条">🗑</button>
          </div>`);
        }
      }
      body.innerHTML = rows.length
        ? `<div class="lc-mem-group">这个会话的记忆 <span class="muted">（共 ${total} 条，删了就是真删）</span>
             <button class="lc-mem-clear" data-user="" id="lc-mem-clear-all">全清</button></div>` + rows.join('')
        : '<div class="lc-mem-group">这个会话还没有记忆</div>'
          + '<div class="lc-mem-empty muted">她说「记住：……」之后，这里就会出现。每个人的记忆单独一份，可以逐条删。</div>';
    } catch (e) {
      body.innerHTML = `<div class="muted" style="padding:12px">读取失败：${esc(e.message)}</div>`;
    }
  }

  async function deleteMemory(userId, index, rowEl) {
    try {
      const data = await api('/api/local-chat/memory/delete', {
        method: 'POST',
        body: JSON.stringify({ session, userId, indexes: [Number(index)] })
      });
      rowEl?.remove();
      if (typeof toast === 'function') toast(`已删掉这条记忆（剩 ${data.left ?? '?'} 条）`, 'ok');
    } catch (e) {
      if (typeof toast === 'function') toast(`删除失败：${e.message}`, 'error');
    }
  }

  async function clearMemory(userId) {
    const ask = typeof uiConfirm === 'function'
      ? await uiConfirm(userId ? '清空这个人的全部记忆？' : '清空整个会话的记忆？删了就找不回来了。')
      : window.confirm('确定清空记忆？');
    if (!ask) return;
    try {
      await api('/api/local-chat/memory/clear', { method: 'POST', body: JSON.stringify({ session, userId: userId || '' }) });
      openMemory();
      if (typeof toast === 'function') toast('已清空', 'ok');
    } catch (e) {
      if (typeof toast === 'function') toast(`清空失败：${e.message}`, 'error');
    }
  }

  function init() {
    const sendBtn = $id('livechat-send');
    const input = $id('livechat-input');
    const clearBtn = $id('livechat-clear');
    if (!sendBtn || !input) return;

    api('/api/local-chat/available').then((d) => {
      if (!d || !d.enabled) return;
      const tab = $id('tab-livechat');
      const view = $id('view-livechat');
      if (tab) {
        tab.classList.remove('hidden');
        if (d.title) tab.textContent = d.title;
      }
      if (view) view.classList.remove('hidden');
      loadSessions();
      load();
    }).catch(() => { /* 接口 404 = 插件没开，保持隐藏 */ });

    sendBtn.addEventListener('click', send);
    input.addEventListener('input', () => autoGrow(input));
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
        e.preventDefault();
        send();
      }
    });
    if (clearBtn) {
      clearBtn.addEventListener('click', () => {
        messages = [];
        render();
        if (typeof toast === 'function') toast('已清屏（记录还在存档里）', 'ok');
      });
    }
    document.querySelectorAll('.tab').forEach((t) => {
      t.addEventListener('click', () => { stopPolling(); });
    });

    // 会话切换 / 新建
    const sessionSel = $id('livechat-session');
    if (sessionSel) sessionSel.addEventListener('change', () => switchSession(sessionSel.value));
    const newBtn = $id('livechat-new');
    if (newBtn) newBtn.addEventListener('click', createSession);
    const delBtn = $id('livechat-del-session');
    if (delBtn) delBtn.addEventListener('click', deleteSession);

    // 消息上的 ✏ / 🗑
    const host = $id('livechat-messages');
    if (host) {
      host.addEventListener('click', (e) => {
        const btn = e.target.closest('.lc-tool');
        if (!btn) return;
        const row = btn.closest('.lc-row');
        if (!row) return;
        const id = Number(row.dataset.id);
        if (!Number.isFinite(id)) return;
        if (btn.dataset.act === 'edit') startEdit(row);
        else if (btn.dataset.act === 'del') deleteOne(row, id);
      });
    }

    // 记忆面板
    const memBtn = $id('livechat-mem-btn');
    const memClose = $id('livechat-mem-close');
    const memBody = $id('livechat-mem-body');
    if (memBtn) memBtn.addEventListener('click', openMemory);
    if (memClose) memClose.addEventListener('click', () => $id('livechat-mem-panel')?.classList.add('hidden'));
    if (memBody) {
      memBody.addEventListener('click', (e) => {
        const del = e.target.closest('.lc-mem-del');
        if (del) {
          const row = del.closest('.lc-mem-row');
          deleteMemory(row?.dataset.u, row?.dataset.i, row);
          return;
        }
        const clr = e.target.closest('.lc-mem-clear');
        if (clr) clearMemory(clr.dataset.user || '');
      });
    }

    bindSse();
  }

  window.LiveChat = { onShow, load };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
